import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Plan View - GeoFence","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/plan_view/plan_geofence.md","filePath":"en/qgc-user-guide/plan_view/plan_geofence.md"}`),a={name:`en/qgc-user-guide/plan_view/plan_geofence.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-view-geofence" tabindex="-1">Plan View - GeoFence <a class="header-anchor" href="#plan-view-geofence" aria-label="Permalink to “Plan View - GeoFence”">​</a></h1><p>GeoFences allow you to create virtual regions within which the vehicle can fly, or in which it is <em>not allowed</em> to fly. You can also configure the action taken if you fly outside permitted areas.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>If GeoFence is not supported by the connected vehicle firmware, the <strong>Fence</strong> tab shows a message saying so instead of the GeoFence options.</p></div><h2 id="create-a-geofence" tabindex="-1">Create a GeoFence <a class="header-anchor" href="#create-a-geofence" aria-label="Permalink to “Create a GeoFence”">​</a></h2><p>To create a GeoFence:</p><ol><li><p>Navigate to the Plan View</p></li><li><p>Select the <strong>Fence</strong> tab in the <a href="./plan_view.html#plan-editor-panel">Plan Editor Panel</a>. The tab is enabled once the <a href="./plan_view.html#planned-home">planned home position</a> is set.</p></li><li><p>Insert a circular or polygon region by pressing the <strong>+ Circle</strong> or <strong>+ Polygon</strong> button at the top of the tab. A new region will be added to the map and to the list of fences below the buttons, and it becomes the selected fence.</p></li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>You can create multiple regions by pressing the buttons multiple times, allowing complex geofence definitions to be created.</p></div><ul><li><p>Circular region:</p><ul><li>Move the region by dragging the central dot on the map</li><li>Resize the circle by dragging the dot on the edge of the circle (or you can change the <strong>Radius</strong> value in the fence inspector).</li></ul></li><li><p>Polygon region:</p><ul><li>Move the vertices by dragging the filled dots</li><li>Create new vertices by clicking the &quot;unfilled&quot; dots on the lines between the filled vertices.</li></ul></li></ul><ol><li><p>By default new regions are created as <em>inclusion</em> zones (vehicles must stay within the region). Change them to exclusion zones (where the vehicle can&#39;t travel) by selecting <em>Exclude</em> in the fence inspector.</p></li><li><p>Check a circular region&#39;s <em>Center on home</em> checkbox in the fence inspector to keep it centred on the vehicle home position. The checkbox is offered when connected to a vehicle whose firmware supports these circles.</p></li></ol><p>The list also has a <strong>Breach return point</strong> entry. Select it and press <strong>Set at map center</strong> to add an optional point (with altitude) that the vehicle will fly to if it breaches the fence.</p><h2 id="edit-delete-a-geofence" tabindex="-1">Edit/Delete a GeoFence <a class="header-anchor" href="#edit-delete-a-geofence" aria-label="Permalink to “Edit/Delete a GeoFence”">​</a></h2><p>Select a GeoFence region to edit by clicking it in the list on the <strong>Fence</strong> tab. You can then edit the region on the map as described in the previous section, and change its settings in the inspector below the list.</p><p>Delete the selected region by pressing the delete button (trash icon) in the inspector.</p><h2 id="upload-a-geofence" tabindex="-1">Upload a GeoFence <a class="header-anchor" href="#upload-a-geofence" aria-label="Permalink to “Upload a GeoFence”">​</a></h2><p>The GeoFence is uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};